// Moltiplicatore di velocità del tempo
float timeVar = ubuf.u_time * 2.0;

// Genera onde sui tre assi spaziali
float waveX = sin(pModel.x * 10.0 + timeVar);
float waveY = sin(pModel.y * 8.0 - timeVar * 0.5);
float waveZ = sin(pModel.z * 12.0 + timeVar * 0.8);

// Combina le onde e normalizza il valore tra 0.0 e 1.0
float combinedWave = (waveX + waveY + waveZ) / 3.0;
combinedWave = combinedWave * 0.5 + 0.5;

// Sfuma tra due colori accesi in base all'onda
vec3 colFucsia = vec3(0.8, 0.1, 0.5); // Fucsia
vec3 colLime = vec3(0.1, 0.9, 0.4); // Verde lime
textureCol = mix(colFucsia, colLime, combinedWave);
